#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail
# Run from PowerShell, bash may put Windows System32 (whose find.exe differs)
# ahead of its own tools; prefer the Unix ones.
export PATH="/usr/bin:/bin:$PATH"

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: connect cracked to Google Play Games Services.
# Run from Git Bash:  bash tools/play_games_setup.sh
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

cd "$(dirname "$0")/.."

# Pages open in Firefox, where you're signed in to the Play Console.
FIREFOX="${FIREFOX:-/c/Program Files/Mozilla Firefox/firefox.exe}"
if [[ -x "$FIREFOX" ]]; then
  open_url() {
    printf '  %s↗ opening in Firefox%s %s\n' "$GREEN" "$RESET" "$1"
    "$FIREFOX" -new-tab "$1" >/dev/null 2>&1 &
  }
fi
# copy TEXT puts TEXT on the Windows clipboard.
copy() { printf '%s' "$1" | clip.exe && printf '  %s✓ copied to clipboard%s\n' "$GREEN" "$RESET"; }
CONSOLE="https://play.google.com/console"
# Saved answers (never passwords) live in the git-ignored .godot/ folder.
mkdir -p .godot
ENV_FILE=".godot/play_games_setup.env"

PACKAGE="com.cracked.pro"
KEY_ALIAS="cracked"
DEBUG_KEYSTORE="$APPDATA/Godot/keystores/debug.keystore"
GODOT="${GODOT:-$LOCALAPPDATA/Microsoft/WinGet/Packages/GodotEngine.GodotEngine_Microsoft.Winget.Source_8wekyb3d8bbwe/Godot_v4.7.2-stable_win64_console.exe}"
APK="build/cracked.apk"

sha1_of() { # keystore alias password
  keytool -list -v -keystore "$1" -alias "$2" -storepass "$3" 2>/dev/null \
    | grep -E '^\s*SHA1:' | head -n1 | sed -E 's/.*SHA1: *//'
}
cfg_escape() { local s="${1//\\/\\\\}"; printf '%s' "${s//\"/\\\"}"; }

banner "Google Play Games for cracked ($PACKAGE)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Release keystore"
say "Play Games accepts sign-in only from an APK whose signing key it knows."
say "This creates the release key (or reuses one) and prints both SHA-1s."
ask KEYSTORE_PATH "Keystore path (Enter = $HOME/keystores/cracked-release.keystore):"
KEYSTORE_PATH="${KEYSTORE_PATH:-$HOME/keystores/cracked-release.keystore}"
write_env KEYSTORE_PATH "$KEYSTORE_PATH"
if [[ -f "$KEYSTORE_PATH" ]]; then
  note "Found an existing keystore; reusing it."
  ask_secret KEY_PASSWORD "Its password:"
else
  warn "Lose this file or its password and you can never update the game on Play."
  ask_secret KEY_PASSWORD "Choose a password (6+ chars):"
  ask_secret KEY_PASSWORD2 "Type it again:"
  [[ "$KEY_PASSWORD" == "$KEY_PASSWORD2" && ${#KEY_PASSWORD} -ge 6 ]] \
    || { warn "Passwords differ or are too short. Re-run."; exit 1; }
  mkdir -p "$(dirname "$KEYSTORE_PATH")"
  keytool -genkeypair -keystore "$KEYSTORE_PATH" -alias "$KEY_ALIAS" \
    -keyalg RSA -keysize 2048 -validity 10000 \
    -storepass "$KEY_PASSWORD" -keypass "$KEY_PASSWORD" \
    -dname "CN=proobker, O=proobker" >/dev/null
  printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$KEYSTORE_PATH"
  warn "Back it up now (cloud drive / USB) together with the password."
fi
RELEASE_SHA1=$(sha1_of "$KEYSTORE_PATH" "$KEY_ALIAS" "$KEY_PASSWORD")
[[ -n "$RELEASE_SHA1" ]] || { warn "Wrong password, or the alias isn't '$KEY_ALIAS'."; exit 1; }
DEBUG_SHA1=$(sha1_of "$DEBUG_KEYSTORE" androiddebugkey android || true)
say ""
say "${BOLD}Release SHA-1:${RESET} $RELEASE_SHA1"
say "${BOLD}Debug SHA-1:${RESET}   ${DEBUG_SHA1:-(no Godot debug keystore found)}"
printf 'release %s\ndebug   %s\n' "$RELEASE_SHA1" "$DEBUG_SHA1" > .godot/play_games_sha1.txt
note "Saved to .godot/play_games_sha1.txt so you can copy them in stage 3."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Open cracked in the Play Console"
open_url "$CONSOLE"
step "All apps → cracked."
step "Check the package name shown under the app name is $PACKAGE."
note "If it differs (an APK was already uploaded under another name), stop:"
note "package/unique_name in export_presets.cfg must match it."
pause "Press Enter when cracked's dashboard is open."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Play Games Services project + credentials"
say "In cracked's menu in the Play Console:"
step "Grow users → Play Games Services → Setup and management → Configuration."
note "Already set up? Skip to the credentials you're missing, then the Project ID."
step "Pick 'No, my game doesn't use Google APIs' → create a new project."
step "Credentials → Add credential → Android."
step "If asked, open Google Cloud and set up the OAuth consent screen"
note "  (External, app name cracked, your email), then come back."
step "Create the OAuth client: Android, package $PACKAGE, SHA-1 (release):"
say "    ${BOLD}$RELEASE_SHA1${RESET}"
copy "$RELEASE_SHA1"
pause "Press Enter after saving the release credential."
if [[ -n "$DEBUG_SHA1" ]]; then
  step "Add a second Android credential with the debug SHA-1:"
  say "    ${BOLD}$DEBUG_SHA1${RESET}"
  copy "$DEBUG_SHA1"
  pause "Press Enter after saving the debug credential."
fi
step "If cracked uses Play App Signing (Test and release → App integrity),"
note "  add a third credential with the 'App signing key certificate' SHA-1."
note "  Installs from a Play testing track are signed with that key, not yours."
step "On the Configuration page, copy the numeric Project ID (e.g. 123456789012)."
ask PGS_GAME_ID "Paste the Project ID:"
[[ "$PGS_GAME_ID" =~ ^[0-9]+$ ]] || { warn "The Project ID is digits only. Re-run."; exit 1; }
write_env PGS_GAME_ID "$PGS_GAME_ID"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Testers"
say "Until the Play Games configuration is published, only its testers can sign in."
step "Play Games Services → Setup and management → Testers → Add testers."
say "If the page lets you pick your existing email list, pick it and skip the rest."
say "Otherwise this copies the list's addresses so you can paste them all at once."
note "Get them from Test and release → Testing → (your track) → Testers → the list,"
note "or any CSV/text file holding the addresses."
ask TESTERS_FILE "Path to a file with the tester emails (Enter to skip):"
if [[ -n "$TESTERS_FILE" && -f "$TESTERS_FILE" ]]; then
  write_env TESTERS_FILE "$TESTERS_FILE"
  emails=$(grep -oiE '[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}' "$TESTERS_FILE" | tr 'A-Z' 'a-z' | sort -u)
  count=$(printf '%s\n' "$emails" | grep -c @ || true)
  say "Found ${BOLD}$count${RESET} addresses."
  copy "$(printf '%s\n' "$emails" | paste -sd, -)"
  step "Paste them into the Add testers box and save."
else
  step "Add at least the Google account signed in on your phone, and save."
fi
note "Once your testers are in, you can instead publish the configuration"
note "(Play Games Services → Review and publish), and then anyone can sign in."
pause "Press Enter when the testers are saved."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Write the Godot export settings"
sed -i -E "s|^godot_play_game_services/game_id=.*|godot_play_game_services/game_id=\"$PGS_GAME_ID\"|" export_presets.cfg
printf '  %s✓ wrote%s game_id → export_presets.cfg\n' "$GREEN" "$RESET"
CRED=.godot/export_credentials.cfg
if [[ -f "$CRED" ]]; then cp "$CRED" "$CRED.bak"; note "Backed up the old $CRED to $CRED.bak"; fi
{
  printf '[preset.0]\n\nscript_encryption_key=""\n\n[preset.0.options]\n\n'
  printf 'keystore/debug=""\nkeystore/debug_user=""\nkeystore/debug_password=""\n'
  printf 'keystore/release="%s"\n' "$(cfg_escape "$(cygpath -m "$KEYSTORE_PATH")")"
  printf 'keystore/release_user="%s"\n' "$KEY_ALIAS"
  printf 'keystore/release_password="%s"\n' "$(cfg_escape "$KEY_PASSWORD")"
} > "$CRED"
printf '  %s✓ wrote%s release keystore → %s (git-ignored)\n' "$GREEN" "$RESET" "$CRED"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Leaderboard and achievements (optional)"
say "The game can post a total-score leaderboard and unlock achievements"
say "for the first clear of levels 10, 25, 50 and 99."
if confirm "Set these up now?"; then
  step "Play Games Services → Leaderboards → Create leaderboard (e.g. 'Total score')."
  ask PGS_LEADERBOARD "Paste its ID (CgkI..., Enter to skip):"
  write_env PGS_LEADERBOARD "$PGS_LEADERBOARD"
  sed -i -E "s|^const LEADERBOARD_ID := \".*\"|const LEADERBOARD_ID := \"$PGS_LEADERBOARD\"|" scripts/game/play_games.gd
  note "Icons: prompts 2–6 in build/store/chatgpt_prompts.md. Fit each download with"
  note "  python tools/fit_image.py <download> build/store/<name>.png 512 512"
  step "Achievements → Create one each for levels 10, 25, 50 and 99."
  for n in 10 25 50 99; do
    ask "PGS_ACH_$n" "Level $n achievement ID:"
    v="PGS_ACH_$n"; write_env "$v" "${!v}"
  done
  sed -i -E "s|^const ACHIEVEMENTS := \{.*\}|const ACHIEVEMENTS := {10: \"$PGS_ACH_10\", 25: \"$PGS_ACH_25\", 50: \"$PGS_ACH_50\", 99: \"$PGS_ACH_99\"}|" scripts/game/play_games.gd
  printf '  %s✓ wrote%s IDs → scripts/game/play_games.gd\n' "$GREEN" "$RESET"
else
  SKIPPED+=("leaderboard/achievement IDs (constants at the top of scripts/game/play_games.gd)")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Store listing graphics"
say "Ready in build/store/: icon_512.png and 8 real 1920×1080 gameplay screenshots"
note "(re-take them: godot --path . --resolution 1920x1080 res://tests/capture_store.tscn)"
say "The feature graphic (1024×500) comes from ChatGPT: prompt 1 in"
say "  build/store/chatgpt_prompts.md"
ask FEATURE_SRC "Path to the downloaded feature image (Enter to skip):"
if [[ -n "$FEATURE_SRC" && -f "$FEATURE_SRC" ]]; then
  python tools/fit_image.py "$FEATURE_SRC" build/store/feature_graphic.png 1024 500
else
  SKIPPED+=("feature graphic: python tools/fit_image.py <download> build/store/feature_graphic.png 1024 500")
fi
open_url "$CONSOLE"
step "cracked → Grow users → Store presence → Main store listing → Graphics."
step "App icon: build/store/icon_512.png. Feature graphic: build/store/feature_graphic.png."
step "Phone screenshots: pick 4–8 from build/store/screenshot_level_*.png. Save."
explorer.exe "$(cygpath -w build/store)" >/dev/null 2>&1 || true
pause "Press Enter when the listing is saved."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Build the release APK"
[[ -f "$GODOT" ]] || { warn "Godot not found at $GODOT. Re-run with GODOT=/path/to/godot_console.exe"; exit 1; }
mkdir -p build
rm -f "$APK"
say "Exporting $APK (Gradle build, a few minutes the first time)…"
GODOT_ANDROID_KEYSTORE_RELEASE_PATH="$(cygpath -m "$KEYSTORE_PATH")" \
GODOT_ANDROID_KEYSTORE_RELEASE_USER="$KEY_ALIAS" \
GODOT_ANDROID_KEYSTORE_RELEASE_PASSWORD="$KEY_PASSWORD" \
  "$GODOT" --headless --path . --export-release "Android" "$APK" 2>&1 | tail -n 15 || true
[[ -f "$APK" ]] || { warn "Export failed; see the output above."; exit 1; }
printf '  %s✓ built%s %s\n' "$GREEN" "$RESET" "$APK"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Install and sign in"
say "Plug in the phone with USB debugging on (Settings → Developer options)."
pause "Press Enter when it's connected and you've allowed the USB prompt."
if ! adb get-state >/dev/null 2>&1; then
  SKIPPED+=("install: adb install -r $APK")
  warn "No device found. Install later with: adb install -r $APK"
else
  if ! out=$(adb install -r "$APK" 2>&1); then
    if [[ "$out" == *UPDATE_INCOMPATIBLE* ]] \
       && confirm "A debug build is installed (different key). Uninstall it? Local progress on the phone is lost."; then
      adb uninstall "$PACKAGE" >/dev/null
      adb install "$APK"
    else
      printf '%s\n' "$out"; SKIPPED+=("install: adb install -r $APK")
    fi
  fi
  adb shell monkey -p "$PACKAGE" -c android.intent.category.LAUNCHER 1 >/dev/null 2>&1 || true
  say "The game is launching. The menu should show your gamer name or SIGN IN."
  note "Sign-in errors: adb logcat -s godot GodotPlayGameServices"
  note "'Developer error' = this APK's SHA-1 isn't a credential from stage 3."
fi
pause

finish
